/**
 * Connect Four bitboard engine.
 *
 * Board layout: 7 columns x 7 bits per column (6 playable rows + 1 sentinel
 * row on top to prevent wrap-around false positives on horizontal/diagonal shifts).
 * Bit index = row + column * 7, row 0 is the bottom row.
 */
export const WIDTH = 7;
export const HEIGHT = 6;
export const H1 = HEIGHT + 1; // bits per column (incl. sentinel)

/** Stones of the side to move / of the opponent. */
export interface Position {
  cur: bigint;
  opp: bigint;
}

export const COLUMN_MASKS: bigint[] = [];
export const BOTTOM_MASKS: bigint[] = [];
export const TOP_MASKS: bigint[] = [];
for (let c = 0; c < WIDTH; c++) {
  const base = BigInt(c * H1);
  COLUMN_MASKS[c] = ((1n << BigInt(HEIGHT)) - 1n) << base;
  BOTTOM_MASKS[c] = 1n << base;
  TOP_MASKS[c] = 1n << BigInt(c * H1 + HEIGHT - 1);
}

export const FULL_MASK: bigint = (() => {
  let m = 0n;
  for (let c = 0; c < WIDTH; c++) m |= COLUMN_MASKS[c];
  return m;
})();

export function canPlay(mask: bigint, col: number): boolean {
  return (mask & TOP_MASKS[col]) === 0n;
}

/** The single bit that a stone dropped into `col` would occupy. */
export function moveBit(mask: bigint, col: number): bigint {
  return (mask + BOTTOM_MASKS[col]) & COLUMN_MASKS[col];
}

export function play(p: Position, col: number): Position {
  const bit = moveBit(p.cur | p.opp, col);
  return { cur: p.opp, opp: p.cur | bit };
}

/** True if the bitboard contains four in a line. */
export function isWin(bb: bigint): boolean {
  // vertical (shift 7)
  let m = bb & (bb >> 7n);
  if (m & (m >> 14n)) return true;
  // horizontal (1), diagonal / (6), diagonal \ (8)
  for (const d of [1n, 6n, 8n]) {
    m = bb & (bb >> d);
    if (m & (m >> 2n * d)) return true;
  }
  return false;
}

/* ------------------------------- evaluation ------------------------------ */

function popcount(n: bigint): number {
  let c = 0;
  while (n) {
    n &= n - 1n;
    c++;
  }
  return c;
}

/** All 69 possible 4-in-a-row windows as bitmask constants. */
export const WINDOWS: bigint[] = (() => {
  const wins: bigint[] = [];
  const bit = (r: number, c: number) => 1n << BigInt(r + c * H1);
  const push = (r: number, c: number, dr: number, dc: number) => {
    let m = 0n;
    for (let i = 0; i < 4; i++) m |= bit(r + i * dr, c + i * dc);
    wins.push(m);
  };
  for (let r = 0; r < HEIGHT; r++) for (let c = 0; c <= WIDTH - 4; c++) push(r, c, 0, 1); // horizontal
  for (let r = 0; r <= HEIGHT - 4; r++) for (let c = 0; c < WIDTH; c++) push(r, c, 1, 0); // vertical
  for (let r = 0; r <= HEIGHT - 4; r++) for (let c = 0; c <= WIDTH - 4; c++) push(r, c, 1, 1); // diag \
  for (let r = 3; r < HEIGHT; r++) for (let c = 0; c <= WIDTH - 4; c++) push(r, c, -1, 1); // diag /
  return wins;
})();

const OPEN3_SCORE = 50;
const OPEN2_SCORE = 8;

/** Simple eval from the perspective of the side to move: counts open 3s and open 2s. */
export function evaluate(p: Position): number {
  let s = 0;
  for (let i = 0; i < WINDOWS.length; i++) {
    const w = WINDOWS[i];
    const mine = popcount(p.cur & w);
    const theirs = popcount(p.opp & w);
    if (theirs === 0) {
      if (mine === 3) s += OPEN3_SCORE;
      else if (mine === 2) s += OPEN2_SCORE;
    } else if (mine === 0) {
      if (theirs === 3) s -= OPEN3_SCORE;
      else if (theirs === 2) s -= OPEN2_SCORE;
    }
  }
  return s;
}

/* ------------------------------ BFS counting ----------------------------- */

/** Distinct positions reachable in exactly `n` plies (dedup by board key). */
export function positionsAtPly(n: number): Set<string> {
  let frontier: Position[] = [{ cur: 0n, opp: 0n }];
  for (let d = 0; d < n; d++) {
    const keys = new Set<string>();
    const next: Position[] = [];
    for (const p of frontier) {
      const mask = p.cur | p.opp;
      for (let c = 0; c < WIDTH; c++) {
        if (!canPlay(mask, c)) continue;
        const q = play(p, c);
        const key = (q.cur | q.opp).toString();
        if (!keys.has(key)) {
          keys.add(key);
          next.push(q);
        }
      }
    }
    frontier = next;
  }
  return new Set(frontier.map((p) => (p.cur | p.opp).toString()));
