import {
  canPlay,
  evaluate,
  FULL_MASK,
  isWin,
  moveBit,
  play,
  Position,
  WIDTH,
} from './engine.js';

export const WIN_SCORE = 1_000_000;
/** Center-first move ordering. */
export const MOVE_ORDER = [3, 2, 4, 1, 5, 0, 6];

export interface SearchResult {
  move: number;
  score: number;
  nodes: number;
}

let nodeCount = 0;
export function resetNodes(): void {
  nodeCount = 0;
}
export function getNodes(): number {
  return nodeCount;
}

function legalCols(mask: bigint): number[] {
  return MOVE_ORDER.filter((c) => canPlay(mask, c));
}

/**
 * Negamax with alpha-beta pruning.
 * Score is from the perspective of the side to move at the node.
 */
function negamax(p: Position, depth: number, alpha: number, beta: number, ply: number): number {
  nodeCount++;
  const mask = p.cur | p.opp;

  if (mask === FULL_MASK) return 0; // draw

  // Immediate winning moves (checked even at depth 0 so tactics are never missed).
  for (const col of MOVE_ORDER) {
    if (!canPlay(mask, col)) continue;
    if (isWin(p.cur | moveBit(mask, col))) return WIN_SCORE - (ply + 1);
  }

  if (depth <= 0) return evaluate(p);

  let best = -Infinity;
  for (const col of legalCols(mask)) {
    const score = -negamax(play(p, col), depth - 1, -beta, -alpha, ply + 1);
    if (score > best) best = score;
    if (best > alpha) alpha = best;
    if (alpha >= beta) break; // prune
  }
  return best;
}

/** Plain minimax without pruning (for node-count comparison). */
function minimax(p: Position, depth: number, ply: number): number {
  nodeCount++;
  const mask = p.cur | p.opp;

  if (mask === FULL_MASK) return 0;

  for (const col of MOVE_ORDER) {
    if (!canPlay(mask, col)) continue;
    if (isWin(p.cur | moveBit(mask, col))) return WIN_SCORE - (ply + 1);
  }

  if (depth <= 0) return evaluate(p);

  let best = -Infinity;
  for (const col of legalCols(mask)) {
    const score = -minimax(play(p, col), depth - 1, ply + 1);
    if (score > best) best = score;
  }
  return best;
}

function rootSearch(
  p: Position,
  depth: number,
  childScore: (child: Position, alpha: number, beta: number, ply: number) => number,
): SearchResult {
  resetNodes();
  nodeCount++;
  const mask = p.cur | p.opp;
  let bestMove = -1;
  let bestScore = -Infinity;
  let alpha = -Infinity;
  for (const col of MOVE_ORDER) {
    if (!canPlay(mask, col)) continue;
    let score: number;
    if (isWin(p.cur | moveBit(mask, col))) {
      score = WIN_SCORE - 1;
    } else {
      score = -childScore(play(p, col), depth - 1, -Infinity, -alpha, 1);
    }
    if (score > bestScore) {
      bestScore = score;
      bestMove = col;
    }
    if (bestScore > alpha) alpha = bestScore;
  }
  return { move: bestMove, score: bestScore, nodes: getNodes() };
}

/** Alpha-beta root search, default depth 8. */
export function searchRoot(p: Position, depth = 8): SearchResult {
  return rootSearch(p, depth, (child, d, a, b, ply) => negamax(child, d, a, b, ply));
}

/** Pure minimax root search (no pruning). */
export function searchRootMinimax(p: Position, depth: number): SearchResult {
  return rootSearch(p, depth, (child, d, _a, _b, ply) => minimax(child, d, ply));
}

export { WIDTH };

