import { describe, expect, it } from 'vitest';
import { play, positionsAtPly, Position } from '../src/engine.js';
import { searchRoot, searchRootMinimax } from '../src/search.js';

/** Build a position from a move list; player 1 (then alternating) moves first. */
function fromMoves(moves: number[]): Position {
  let p: Position = { cur: 0n, opp: 0n };
  for (const m of moves) p = play(p, m);
  return p;
}

describe('connect four engine', () => {
  it('finds an immediate vertical win', () => {
    // Player 1 has three stones stacked in column 3 and is to move.
    const p = fromMoves([3, 0, 3, 0, 3, 0]);
    const r = searchRoot(p, 8);
    console.log('vertical win ->', JSON.stringify(r));
    expect(r.move).toBe(3);
    expect(r.score).toBeGreaterThan(900_000); // winning score
  });

  it('blocks an opponent\'s immediate win', () => {
    // Player 2 has three stones stacked in column 5; player 1 must block.
    const p = fromMoves([3, 5, 0, 5, 1, 5]);
    const r = searchRoot(p, 8);
    console.log('block ->', JSON.stringify(r));
    expect(r.move).toBe(5);
  });

  it('BFS position counts for n=1..4 plies are 7, 49, 238, 1120', () => {
    const expected = [7, 49, 238, 1120];
    for (let n = 1; n <= 4; n++) {
      const count = positionsAtPly(n).size;
      console.log(`ply ${n}: ${count} distinct positions`);
      expect(count).toBe(expected[n - 1]);
    }
  });

  it('alpha-beta explores fewer nodes than pure minimax at depth 6', () => {
    const start: Position = { cur: 0n, opp: 0n };
    const ab = searchRoot(start, 6);
    const mm = searchRootMinimax(start, 6);
    console.log(
      `depth 6 node counts: alpha-beta=${ab.nodes}, minimax=${mm.nodes} ` +
        `(${(100 * ab.nodes / mm.nodes).toFixed(1)}%)`,
    );
    expect(ab.move).toBe(3); // sanity: both agree on the center opening
    expect(mm.move).toBe(3);
    expect(ab.nodes).toBeLessThan(mm.nodes);
  });
});

