export function isWin(bb: bigint): boolean {
  // vertical: +1 bit within a column
  let m = bb & (bb >> 1n);
  if (m & (m >> 2n)) return true;
  // horizontal (+H1), diagonal / (-...+H1-1 = 6), diagonal \ (+H1+1 = 8);
  // the sentinel row prevents wrap-around false positives.
  for (const d of [7n, 6n, 8n]) {
    m = bb & (bb >> d);
    if (m & (m >> 2n * d)) return true;
  }
  return false;
}

